package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; import java.time.*; @RestController @RequestMapping("/appointment") public class AppointmentController{private final AppointmentService s;public AppointmentController(AppointmentService s){this.s=s;}@PostMapping public ResponseEntity<AppointmentDTO> create(@Valid @RequestBody AppointmentDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<AppointmentDTO> all(){return s.all();}@GetMapping("/{id}") public AppointmentDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public AppointmentDTO update(@PathVariable Long id,@Valid @RequestBody AppointmentDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@GetMapping("/doctor/{id}") public List<AppointmentDTO> doctorDate(@PathVariable Long id,@RequestParam LocalDate date){return s.doctorDate(id,date);}@GetMapping("/doctor/{id}/count") public long count(@PathVariable Long id){return s.totalForDoctor(id);}}
